];

if (action === 'create' || body.name) {
  const newPatient = {
    id: body.patientId || `P${1000 + defaultPatients.length + 1}`,
    name: body.name,
    phone: body.phone,
    language: body.language || 'English',
    dischargeDate: body.dischargeDate || new Date().toISOString().split('T')[0],
    processingStatus: 'Pending',
    whatsappStatus: 'Pending',
    diagnosis: [],
    medications: [],
    diet: [],
    restrictions: [],
    followUp: [],
    warningSigns: [],
    patientExplanation: ''
  };
  return [{ json: { status: 'success', data: newPatient } }];
}

if (action === 'get' && body.patientId) {
  const found = defaultPatients.find(p => p.id === body.patientId);
  return [{ json: { status: 'success', data: found || null } }];
}

if (action === 'stats') {
  return [{
    json: {
      status: 'success',
      data: {
        totalPatients: defaultPatients.length,
        summariesProcessed: defaultPatients.filter(p => p.processingStatus === 'Completed').length,
        messagesSent: 4,
        pendingProcessing: defaultPatients.filter(p => p.processingStatus !== 'Completed').length
      }
    }
  }];
}

return [{ json: { status: 'success', data: defaultPatients } }];
